destroyWithCtx = async (
  ctx: APIContext,
  eventOpts?: EventOverrideOptions
): Promise<void> => {
  const { user } = ctx.state.auth;
  const { transaction } = ctx.state;
  let deleted = false;

  if (this.collectionId) {
    const collection = await Collection.findByPk(this.collectionId, {
      includeDocumentStructure: true,
      transaction,
      lock: transaction?.LOCK.NO_KEY_UPDATE,
      paranoid: false,
    });

    if (!this.archivedAt || (this.archivedAt && collection?.archivedAt)) {
      await collection?.deleteDocument(this, user, { transaction });
      deleted = true;
    }
  }

  if (!deleted) {
    this.deletedById = user.id;
    await this.destroy({ transaction });
  }

  // The deleting user has already been persisted by destroy, mark the field
  // as changed so that the save below still publishes the delete event.
  this.deletedById = user.id;
  this.deletedBy = user;
  this.changed("deletedById", true);
  await this.saveWithCtx(ctx, undefined, { name: "delete", ...eventOpts });
};

